<script setup lang="ts">
import{onMounted,ref,watch}from'vue';import AdminSidebar from '../../components/admin/AdminSidebar.vue';import{vendorAdminAPI,getApiErrorMessage}from'../../services/api';import type{VendorOrderShare}from'../../services/api';import StatusBadge from'../../components/StatusBadge.vue';
const items=ref<VendorOrderShare[]>([]),loading=ref(true),error=ref(''),status=ref('shipped'),vendor=ref(''),page=ref(1),totalPages=ref(1),acting=ref<number|null>(null),tabs=['pending','confirmed','shipped','received','cancelled'];async function load(){loading.value=true;error.value='';try{const r=await vendorAdminAPI.getIncoming({status:status.value,vendor:vendor.value,page:page.value,per_page:20});items.value=r.items;totalPages.value=r.totalPages}catch(e:unknown){error.value=getApiErrorMessage(e,'Incoming goods could not be loaded.')}finally{loading.value=false}}watch([status,vendor],()=>{page.value=1;void load()});async function received(o:VendorOrderShare){acting.value=o.order_id;try{await vendorAdminAPI.markReceived(o.order_id,o.vendor_id||0);await load()}catch(e:unknown){error.value=getApiErrorMessage(e,'Could not mark goods received.')}finally{acting.value=null}}function date(v:string){return new Date(v).toLocaleDateString('en-KE',{day:'numeric',month:'short',year:'numeric'})}onMounted(load)
</script><template><div class="admin-page-shell min-h-screen bg-gray-50"><AdminSidebar /><main class="incoming"><header><p>WAREHOUSE</p><h1>Incoming goods</h1></header><nav class="tabs"><button v-for="tab in tabs" :key="tab" :class="{active:status===tab}" @click="status=tab">{{tab==='shipped'?'On their way':tab.charAt(0).toUpperCase()+tab.slice(1)}}</button></nav><input v-model="vendor" class="vendor-filter" placeholder="Vendor code or ID"/><div v-if="loading" class="state">Loading goods...</div><div v-else-if="error" class="state error">{{error}}</div><div v-else-if="!items.length" class="state">No vendor goods found.</div><div v-else class="goods"><article v-for="o in items" :key="`${o.order_id}-${o.vendor_id}`"><header><div><strong>{{o.vendor_code}}</strong><span>{{o.business_name}}</span></div><StatusBadge :status="o.status"/></header><h2>{{o.order_number}}</h2><p class="date">Placed {{date(o.placed_at)}} <span v-if="o.shipped_at">&middot; Sent {{date(o.shipped_at)}}</span></p><ul><li v-for="item in o.items" :key="item.product_id"><span>{{item.name}}</span><b>{{item.quantity}} x KSh {{item.unit_price.toLocaleString()}}</b></li></ul><footer><strong>Subtotal: KSh {{o.subtotal.toLocaleString()}}</strong><button v-if="o.status==='shipped'" :disabled="acting===o.order_id" @click="received(o)">{{acting===o.order_id?'Saving...':'Mark received'}}</button></footer></article></div></main></div></template><style scoped>.incoming{min-height:100vh;padding:18px 28px}@media(min-width:801px){.admin-page-shell{padding-left:246px}}.incoming.incoming>header p{margin:0;color:#075397;font-size:.66rem;font-weight:800}.incoming>header h1{margin:4px 0 16px}.tabs{display:flex;gap:5px;margin-bottom:10px;overflow:auto}.tabs button{height:38px;padding:0 12px;border:1px solid #dbe3ec;border-radius:6px;background:#fff;font-weight:750}.tabs button.active{border-color:#075397;background:#075397;color:#fff}.vendor-filter{width:min(280px,100%);height:42px;margin-bottom:14px;padding:0 10px;border:1px solid #dbe3ec;border-radius:6px}.goods{display:grid;grid-template-columns:repeat(2,1fr);gap:12px}.goods article{padding:16px;border:1px solid #e6ebf1;border-radius:8px;background:#fff}.goods article>header{display:flex;justify-content:space-between}.goods article>header div{display:flex;flex-direction:column}.goods article>header strong{color:#075397}.goods article>header span{color:#64748b;font-size:.75rem}.goods h2{margin:12px 0 3px}.date{margin:0;color:#64748b;font-size:.72rem}.goods ul{list-style:none;padding:8px 0;margin:8px 0;border-top:1px solid #edf0f3;border-bottom:1px solid #edf0f3}.goods li{display:flex;justify-content:space-between;padding:5px 0}.goods li b{font-size:.78rem}.goods footer{display:flex;justify-content:space-between;align-items:center}.goods footer button{height:40px;padding:0 12px;border:0;border-radius:6px;background:#ff7900;color:#fff;font-weight:800}.state{padding:30px;text-align:center;border:1px solid #e6ebf1;border-radius:8px;background:#fff}.error{color:#b42318}@media(max-width:760px){.incoming{padding:14px}.goods{grid-template-columns:1fr}.goods footer{align-items:flex-end;gap:8px}.goods footer strong{max-width:160px}}</style>